const load=async()=>{const[p,a,e,c]=await Promise.all([supabase.from("penyes").select("*").order("nombre"),supabase.from("actos").select("*").order("dia"),supabase.from("eventos").select("*").order("dia"),supabase.from("site_content").select("*")]);setPenyes(p.data??[]);setActos(a.data??[]);setEventos(e.data??[]);const loadedContent=Object.fromEntries((c.data??[]).map((x:any)=>[x.clave,x.valor]));setContent(loadedContent);try{const parsed=JSON.parse(loadedContent["avisos_json"]||"[]");setNotices(Array.isArray(parsed)?parsed:[]);}catch{setNotices([]);}try{const parsed=JSON.parse(loadedContent["noticias_json"]||"[]");const guardadas=Array.isArray(parsed)?parsed:[];const response=await fetch("/noticias-automaticas.json",{cache:"no-store"});const automaticas=response.ok?await response.json():[];const feed=Array.isArray(automaticas)?automaticas.map((n:any)=>({...n,automatico:true})):[];const respaldo=[noticiaCestaNavidad2027,noticiaCuBaTa2027,noticiaDesfileHumor2026];let ocultas:string[]=[];try{const parsedHidden=JSON.parse(loadedContent["noticias_ocultas_json"]||"[]");ocultas=Array.isArray(parsedHidden)?parsedHidden.map((id:any)=>String(id)):[];}catch{ocultas=[];}setHiddenNewsIds(ocultas);const combinadas=[...guardadas,...feed,...respaldo];const unicas=combinadas.filter((n:any,index:number,array:any[])=>n?.id&&array.findIndex((x:any)=>String(x.id)===String(n.id))===index&&!ocultas.includes(String(n.id)));setNewsItems(unicas);}catch{setNewsItems([noticiaCestaNavidad2027,noticiaCuBaTa2027,noticiaDesfileHumor2026]);}try{const ids=JSON.parse(loadedContent["noticias_destacadas_json"]||"[]");setFeaturedNewsIds(Array.isArray(ids)?ids.map((id:any)=>String(id)):[]);}catch{setFeaturedNewsIds([]);}try{const points=JSON.parse(loadedContent["mapa_puntos_json"]||"[]");setMapPoints(Array.isArray(points)?points:[]);}catch{setMapPoints([]);}setHeroPreview(loadedContent["hero_image_path"]?(loadedContent["hero_image_path"].startsWith("http")?loadedContent["hero_image_path"]:supabase.storage.from("penyes").getPublicUrl(loadedContent["hero_image_path"]).data.publicUrl):"");const failures=[["peñas",p.error],["programa",a.error],["eventos",e.error],["contenido de portada",c.error]].filter((item:any)=>item[1]);setMessage(failures.length?"Carga parcial. "+failures.map((item:any)=>item[0]+": "+item[1].message+" (código "+(item[1].code??"sin código")+")").join(" · "):"Datos cargados correctamente.");};
