const login=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);setMessage("Comprobando acceso…");try{const{data,error}=await supabase.auth.signInWithPassword({email:email.trim(),password});if(error)throw error;if(data.user?.email?.toLowerCase()!==ADMIN){await supabase.auth.signOut();throw new Error("Esta cuenta no tiene permiso de administración.");}setPassword("");setMessage("Acceso correcto.");}catch(err){const detail=err instanceof Error?err.message:String(err);setMessage(/email logins are disabled|email provider is disabled/i.test(detail)?"Supabase tiene desactivado el proveedor Email. Actívalo en Authentication → Sign In / Providers → Email. Este acceso utiliza contraseña y no envía correos.":/invalid login credentials/i.test(detail)?"Correo o contraseña incorrectos. Comprueba que el usuario existe en Supabase Authentication → Users y que tiene una contraseña configurada.": "No se pudo iniciar sesión: "+detail);}finally{setBusy(false);}}
